import {CLIP_BEATS} from './featured-clip.js';
import {videoLesson,observedBeats,labels,discussionKey,canRevealDiscussion} from './studio-model.js';
const $=id=>document.getElementById(id),set=(id,text)=>$(id).textContent=text,film=$('film');
let language='en',mode='fan',unlocked=false,started=false,base='',configReady,renderedKey='',lastBeat='',lastMathSecond=-1;
const sessions=new Map(),cards=new Map(),roleIds=['analyst','reviewer','presenter'];
const local=location.hostname==='127.0.0.1'||location.hostname==='localhost';
const copy=(en,es,pt)=>language==='es'?es:language==='pt'?pt:en;
const key=()=>discussionKey(language,mode),clock=t=>`00:${Math.floor(t).toString().padStart(2,'0')}`;
const el=(tag,className,text)=>{const node=document.createElement(tag);if(className)node.className=className;if(text!==undefined)node.textContent=text;return node;};
film.muted=true;
configReady=fetch('api-config.json').then(r=>r.json()).then(c=>{base=local?'':c.baseUrl||'';}).catch(()=>{});
async function seek(at){film.pause();if(film.readyState<1)await new Promise((resolve,reject)=>{const done=()=>{clearTimeout(timer);film.removeEventListener('loadedmetadata',done);resolve();},timer=setTimeout(()=>{film.removeEventListener('loadedmetadata',done);reject(Error('Video not ready'));},8000);film.addEventListener('loadedmetadata',done);film.load();});film.currentTime=Math.max(0,Math.min(8,at));started=true;$('hero-play').hidden=true;renderPlayback();}
function buildBeats(){const beats=observedBeats(8,language);$('beats').replaceChildren();for(const [i,b]of beats.entries()){const button=el('button','beat');button.dataset.id=b.id;button.setAttribute('aria-label',`${copy('Replay','Repetir','Rever')}: ${b.title}`);button.append(el('b','',`0${i+1}`),el('strong','',b.title),el('small','',`${b.at.toFixed(2)} s`));button.addEventListener('click',()=>seek(b.at).catch(mediaError));$('beats').append(button);}}
function renderLesson(force=false){const t=Math.min(8,film.currentTime||0),story=videoLesson(t,mode,language);set('angle-clock',clock(t));set('current-time',clock(t));$('scrub').value=t;const second=Math.floor(t*10);if(!force&&lastBeat===story.activeId&&(mode!=='math'||lastMathSecond===second))return;lastBeat=story.activeId;lastMathSecond=second;set('angle-title',story.title);set('angle-body',story.body);set('angle-kicker',labels[language][mode]);$('math-card').hidden=!story.math;set('math-card',story.math||'');$('film-caption').hidden=!story.activeId;set('caption-phase',copy('THE REVIEWED MOMENT','EL MOMENTO REVISADO','O MOMENTO REVISADO'));set('caption-line',story.title);for(const button of $('beats').children){const selected=button.dataset.id===story.activeId;button.classList.toggle('selected',selected);button.setAttribute('aria-current',String(selected));}const list=$('evidence-list');list.replaceChildren();for(const b of story.evidence){const row=el('div','evidence-item'),button=el('button','',`${b.at.toFixed(2)} s · ${b.title} ↗`);button.addEventListener('click',()=>seek(b.at).catch(mediaError));row.append(button,el('span','',b.observation));list.append(row);}if(!story.evidence.length)list.append(el('p','evidence-item',copy('Play to reveal the reviewed observations.','Reproduce para ver las observaciones.','Reproduza para ver as observações.')));}
function renderPlayback(){set('play',film.paused?'▶':'Ⅱ');$('play').setAttribute('aria-label',film.paused?'Play film':'Pause film');renderLesson();if(canRevealDiscussion(film.currentTime,unlocked)&&!unlocked){unlocked=true;renderDiscussion();if(!sessions.has(key()))startDiscussion();}}
function emptyDesk(message){$('discussion').replaceChildren();const d=el('div','desk-empty');d.append(el('span','empty-symbol','↗'),el('h3','',copy('MORE THAN ONE TAKE.','MÁS DE UNA PERSPECTIVA.','MAIS DE UMA PERSPECTIVA.')),el('p','',message));$('discussion').append(d);cards.clear();}
function cardFor(role){if(cards.has(role))return cards.get(role);if(!cards.size)$('discussion').replaceChildren();const root=el('article',`contribution ${role}`),meta=el('div','speaker-meta'),who=el('div');who.append(el('b','',labels[language][role]),el('small','',role==='analyst'?copy('Find the story','Busca la historia','Encontre a história'):role==='reviewer'?copy('Challenge the claim','Revisa la afirmación','Revise a afirmação'):copy('Bring it together','Une las perspectivas','Reúna as perspectivas')));const state=el('span','post-state');meta.append(el('span','avatar',{analyst:'A',reviewer:'R',presenter:'P'}[role]),who,state);const title=el('h3'),body=el('p'),caution=el('p','caution'),citations=el('div','citations');root.append(meta,title,body,caution,citations);$('discussion').append(root);const c={root,state,title,body,caution,citations};cards.set(role,c);return c;}
function renderDiscussion(){const k=key(),s=sessions.get(k);if(renderedKey!==k){renderedKey=k;cards.clear();$('discussion').replaceChildren();}const pending=s?.pending;set('take-title',copy('THE PLAY. THE WHY. THE PROOF.','LA JUGADA. EL PORQUÉ. LA PRUEBA.','A JOGADA. O PORQUÊ. A PROVA.'));set('take-body',copy('The final takeaway appears after the film and the panel discussion.','La conclusión aparece tras el vídeo y la discusión.','A conclusão aparece após o vídeo e a discussão.'));$('export').disabled=!unlocked||!s?.posts.size;$('discuss').hidden=!unlocked||!!pending;set('discuss',s?.complete?copy('Replay the film ↺','Repetir el vídeo ↺','Rever o vídeo ↺'):copy('Discuss this perspective ↗','Comentar esta perspectiva ↗','Discutir esta perspectiva ↗'));
 if(!unlocked){if(!cards.size)emptyDesk(copy('The panel opens after the final frame. Stay with the play; the discussion will follow.','El panel aparece al final. Sigue la jugada; después llega la discusión.','O painel aparece no final. Acompanhe a jogada; a discussão vem depois.'));set('desk-status',s?copy('Discussion opens after the final frame.','La discusión aparece al final.','A discussão aparece no final.'):copy('Watch the film to open the discussion.','Mira el vídeo para abrir la discusión.','Assista ao vídeo para abrir a discussão.'));return;}
 if(!s){emptyDesk(copy('This perspective is ready to discuss. Choose the button below to bring in the panel.','Esta perspectiva está lista. Pulsa el botón para invitar al panel.','Esta perspectiva está pronta. Use o botão para chamar o painel.'));set('desk-status',`${labels[language][mode]} · ${copy('New perspective','Nueva perspectiva','Nova perspectiva')}`);return;}
 if(!cards.size&&!s.posts.size&&(!s.drafts.size||!$('stream-live').checked))emptyDesk(copy('The analyst is preparing the opening contribution.','El analista prepara su primera intervención.','O analista prepara a primeira contribuição.'));
 for(const role of roleIds){const post=s.posts.get(role),draft=s.drafts.get(role);if(!post&&(!draft||!$('stream-live').checked)){if(cards.has(role)){cards.get(role).root.remove();cards.delete(role);}continue;}const c=cardFor(role);c.root.classList.toggle('draft',!post);c.title.hidden=!post;c.title.textContent=post?.title||'';c.body.textContent=post?.summary||draft.summary;c.state.textContent=post?(post.engine==='azure_openai'?(post.cached?'AI · CACHED':'AI'):copy('REVIEWED NOTES','NOTAS REVISADAS','NOTAS REVISADAS')):copy('DRAFT · UNVALIDATED','BORRADOR · SIN VALIDAR','RASCUNHO · NÃO VALIDADO');c.caution.textContent=post?.caution||'';c.citations.replaceChildren();for(const id of post?.evidence_ids||[]){const b=observedBeats(8,language).find(e=>e.id===id);if(!b)continue;const button=el('button','',`${b.at.toFixed(2)}s · ${b.title} ↗`);button.addEventListener('click',()=>seek(b.at).catch(mediaError));c.citations.append(button);}}
 const final=s.posts.get('presenter');if(final){set('take-title',final.title);set('take-body',final.summary+' '+final.caution);}const fallback=[...s.posts.values()].some(p=>p.engine!=='azure_openai');set('desk-status',s.error?s.error:s.complete?copy(`Full-clip discussion · ${fallback?'reviewed fallback included':'3 AI contributions'} · ${labels[language][mode]}`,`Discusión completa · ${fallback?'incluye notas revisadas':'3 intervenciones de IA'} · ${labels[language][mode]}`,`Discussão completa · ${fallback?'inclui notas revisadas':'3 contribuições de IA'} · ${labels[language][mode]}`):`${labels[language][s.speaker||'analyst']} · ${copy('preparing a contribution…','preparando una intervención…','preparando uma contribuição…')}`);
}
async function startDiscussion(){const k=key();if(sessions.get(k)?.pending||sessions.get(k)?.complete)return;const lang=language,perspective=mode,s={posts:new Map(),drafts:new Map(),pending:true,complete:false,speaker:'analyst'};sessions.set(k,s);if(key()===k){cards.clear();renderDiscussion();}
 try{await configReady;const response=await fetch(base+'/api/desk',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({language:lang,mode:perspective})});if(!response.ok){const error=await response.json().catch(()=>({}));throw Error(error.error||'The AI desk is unavailable. Please retry.');}const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='';while(true){const {done,value}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});if(buffer.length>256000)throw Error('Discussion frame too large');let split;while((split=buffer.indexOf('\n\n'))>=0){const block=buffer.slice(0,split);buffer=buffer.slice(split+2);let type='',data='';for(const line of block.split('\n')){if(line.startsWith('event:'))type=line.slice(6).trim();if(line.startsWith('data:'))data+=line.slice(5).trim();}if(!data)continue;const item=JSON.parse(data);if(type==='speaker')s.speaker=item.role;if(type==='draft'&&roleIds.includes(item.role)&&!s.posts.has(item.role))s.drafts.set(item.role,item);if(type==='post'&&roleIds.includes(item.role)){s.posts.set(item.role,item);s.drafts.delete(item.role);}if(type==='complete'){s.complete=true;s.pending=false;}if(type==='error')throw Error(item.message);if(key()===k)renderDiscussion();}}if(!s.complete)throw Error('The discussion disconnected. Retry to finish it.');}
 catch(error){s.error=error.message;s.drafts.clear();}finally{s.pending=false;if(key()===k)renderDiscussion();}}
function mediaError(){set('desk-status',copy('The video could not play. Check your connection and try again.','No se pudo reproducir el vídeo. Reinténtalo.','Não foi possível reproduzir o vídeo. Tente novamente.'));}
async function playFilm(){try{if(film.ended)film.currentTime=0;await film.play();started=true;$('hero-play').hidden=true;startDiscussion();}catch{mediaError();}}
$('hero-play').addEventListener('click',playFilm);$('play').addEventListener('click',()=>film.paused?playFilm():film.pause());$('restart').addEventListener('click',async()=>{try{await seek(0);await playFilm();}catch{mediaError();}});$('scrub').addEventListener('input',()=>seek(Number($('scrub').value)).catch(mediaError));for(const event of ['timeupdate','play','pause','ended','seeked'])film.addEventListener(event,renderPlayback);film.addEventListener('error',mediaError);
$('slow').addEventListener('click',()=>{film.playbackRate=film.playbackRate===1?.5:1;set('slow',film.playbackRate===1?'1×':'½×');$('slow').setAttribute('aria-pressed',String(film.playbackRate===.5));});$('sound').addEventListener('click',()=>{film.muted=!film.muted;set('sound',film.muted?'Sound off':'Sound on');$('sound').setAttribute('aria-pressed',String(!film.muted));});$('fullscreen').addEventListener('click',()=>{const stage=$('video-stage');if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});else if(stage.requestFullscreen)stage.requestFullscreen().catch(()=>{});else if(film.webkitEnterFullscreen)film.webkitEnterFullscreen();});
for(const button of document.querySelectorAll('[data-mode]'))button.addEventListener('click',()=>{mode=button.dataset.mode;for(const b of document.querySelectorAll('[data-mode]')){b.classList.toggle('selected',b===button);b.setAttribute('aria-pressed',String(b===button));}renderLesson(true);renderDiscussion();});
$('story-language').addEventListener('change',()=>{language=$('story-language').value;for(const b of document.querySelectorAll('[data-mode]'))b.textContent=labels[language][b.dataset.mode];buildBeats();renderLesson(true);renderDiscussion();});$('stream-live').addEventListener('change',renderDiscussion);$('discuss').addEventListener('click',()=>sessions.get(key())?.complete?seek(0).then(playFilm).catch(mediaError):startDiscussion());
$('evidence-toggle').addEventListener('click',()=>{$('evidence-list').hidden=!$('evidence-list').hidden;$('evidence-toggle').setAttribute('aria-expanded',String(!$('evidence-list').hidden));});
$('export').addEventListener('click',()=>{const s=sessions.get(key());if(!unlocked||!s)return;const data={schema:'btr.video-discussion.v1',clip_id:'featured',synthetic:true,video_source:'creator-provided Google Flow film',evidence_source:'manual-review',language,audience:mode,discussion_scope:'full-clip',visible_after_seconds:8,current_video_second:film.currentTime,evidence:observedBeats(8,language),contributions:[...s.posts.values()],complete:s.complete,limits:['No automated video analysis.','Unknown shot result, score, speed and verified player identity.','Citations link observations; they do not certify interpretations.']},url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=el('a');a.href=url;a.download=`btr-video-desk-${language}-${mode}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
function showLab(value){film.pause();$('watch').hidden=value;$('lab').hidden=!value;for(const [id,selected]of [['watch-nav',!value],['lab-nav',value]]){$(id).classList.toggle('selected',selected);$(id).setAttribute('aria-pressed',String(selected));}if(value&&!$('simulation').getAttribute('src'))$('simulation').src='simulation.html?embedded=1';if(!value)$('simulation').contentWindow?.postMessage({type:'btr-pause-lab'},location.origin);}
$('watch-nav').addEventListener('click',()=>showLab(false));$('lab-nav').addEventListener('click',()=>showLab(true));$('back-watch').addEventListener('click',()=>showLab(false));$('about').addEventListener('click',()=>$('about-dialog').showModal());$('close-about').addEventListener('click',()=>$('about-dialog').close());
buildBeats();renderLesson(true);configReady.then(()=>fetch(base+'/api/health')).then(r=>r.json()).then(h=>set('cloud-state',h.video_discussion&&h.ai_configured?'AZURE AI · READY':h.video_discussion?'REVIEWED NOTES MODE':'STUDIO · CONNECTING')).catch(()=>set('cloud-state','STUDIO · CONNECT ON PLAY'));
